<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Authorship\SubordinateClarificationReturnService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:authorship:return-subordinate-clarification',description:'Return an exact clarification to Foundry without altering it')]final class AuthorshipReturnSubordinateClarificationCommand extends Command{public function __construct(private readonly SubordinateClarificationReturnService$s){parent::__construct();}protected function configure():void{$this->addArgument('office',InputArgument::REQUIRED)->addArgument('product-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->returnToFoundry((string)$i->getArgument('office'),(string)$i->getArgument('product-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}if($i->getOption('json'))$o->writeln(json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));else{$o->writeln('<info>SUBORDINATE_CLARIFICATION_RETURNED_TO_FOUNDRY</info> '.$r['return_id']);$o->writeln('Original clarification: PRESERVED IMMUTABLY');}return self::SUCCESS;}}
